<?php
require_once '../config/auth.php';require_role('siswa');
$q=db()->prepare('SELECT a.tanggal,a.status,a.keterangan,mp.nama_mapel,g.nama_guru,k.nama_kelas FROM absensi a JOIN jadwal j ON j.id_jadwal=a.id_jadwal JOIN mata_pelajaran mp ON mp.id_mapel=j.id_mapel JOIN guru g ON g.id_guru=j.id_guru JOIN kelas k ON k.id_kelas=j.id_kelas WHERE a.nis=? ORDER BY a.tanggal DESC,j.jam_mulai DESC');$q->execute([user_reference()]);$rows=$q->fetchAll();$total=count($rows);$hadir=count(array_filter($rows,fn($r)=>$r['status']==='Hadir'));$izin=count(array_filter($rows,fn($r)=>$r['status']==='Izin'));$sakit=count(array_filter($rows,fn($r)=>$r['status']==='Sakit'));$alpa=count(array_filter($rows,fn($r)=>$r['status']==='Alpa'));$page_title='Riwayat Absensi';require '../includes/header.php';require '../includes/sidebar.php';
?><h2>Riwayat Absensi Saya</h2><div class="row g-3 mb-4"><div class="col-6 col-md-3"><div class="card stat p-3"><small>Total</small><h3><?=$total?></h3></div></div><div class="col-6 col-md-3"><div class="card stat p-3 border-success"><small>Hadir</small><h3><?=$hadir?></h3></div></div><div class="col-6 col-md-3"><div class="card stat p-3 border-warning"><small>Izin / Sakit</small><h3><?=$izin+$sakit?></h3></div></div><div class="col-6 col-md-3"><div class="card stat p-3 border-danger"><small>Alpa</small><h3><?=$alpa?></h3></div></div></div><div class="card p-3"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Tanggal</th><th>Mapel</th><th>Guru</th><th>Kelas</th><th>Status</th><th>Keterangan</th></tr></thead><tbody><?php foreach($rows as $r):$color=['Hadir'=>'success','Izin'=>'warning','Sakit'=>'info','Alpa'=>'danger'][$r['status']]??'secondary';?><tr><td><?=e(date('d-m-Y',strtotime($r['tanggal'])))?></td><td><?=e($r['nama_mapel'])?></td><td><?=e($r['nama_guru'])?></td><td><?=e($r['nama_kelas'])?></td><td><span class="badge text-bg-<?=$color?>"><?=e($r['status'])?></span></td><td><?=e($r['keterangan']??'-')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-4">Belum ada riwayat absensi.</td></tr><?php endif;?></tbody></table></div></div><?php require '../includes/footer.php';
